// HasLens applies the HasEdge predicate on the "lens" edge.
func HasLens() predicate.WorkLensWindow {
	return predicate.WorkLensWindow(func(s *sql.Selector) {
		step := sqlgraph.NewStep(
			sqlgraph.From(Table, FieldID),
			sqlgraph.Edge(sqlgraph.M2O, true, LensTable, LensColumn),
		)
		sqlgraph.HasNeighbors(s, step)
	})
}

// HasLensWith applies the HasEdge predicate on the "lens" edge with a given conditions (other predicates).
func HasLensWith(preds ...predicate.WorkLens) predicate.WorkLensWindow {
	return predicate.WorkLensWindow(func(s *sql.Selector) {
		step := newLensStep()
		sqlgraph.HasNeighborsWith(s, step, func(s *sql.Selector) {
			for _, p := range preds {
				p(s)
			}
		})
	})
}

